/**
 * v2 automation payload serialization — the single deep-walk that turns an
 * authored task/trigger config into its handle-form wire shape.
 *
 * Two kinds of reference live in a config, and they're handled differently:
 *   - **Internal `Ref`s** (`ctx.trigger.x`, `ctx.actions.y`, `template(...)`) —
 *     data flow *inside* the automation. Converted here to the platform's
 *     `ValueReference` JSON via the shared, reference-model-agnostic
 *     `serializeRefData` (depends only on `core/ref`). This is the same code
 *     path v1 uses; it moves to `core` at the eventual cutover.
 *   - **`CatalogRef` tokens** (`app.fields.x`, another automation/agent) —
 *     cross-entity refs. Left **in place**; `resolvePayload` swaps them for ids
 *     at deploy. Detected by `__kind ∈ REF_SCOPE`.
 *
 * Everything else passes through untouched.
 */
import { isCatalogToken, slimToken } from "../../catalog/index.js";
import { isRef } from "../shared/ref.js";
// Shared agnostic internal-ref serializer (pure over `core/ref`); relocates to
// `core` when v1's serializer is retired.
import { serializeRefData } from "../../core/wire/ref-serializer.js";
/**
 * Deep-walk a config node: internal `Ref`s → wire ref JSON; `CatalogRef` tokens
 * slimmed to their canonical fields and left in place (resolved at deploy);
 * arrays/objects recursed; scalars passed through.
 */
export function serializeNode(node) {
    if (isRef(node))
        return serializeRefData(node.__data);
    if (isCatalogToken(node))
        return slimToken(node);
    if (Array.isArray(node))
        return node.map(serializeNode);
    if (node !== null && typeof node === "object") {
        const out = {};
        for (const [k, v] of Object.entries(node))
            out[k] = serializeNode(v);
        return out;
    }
    return node;
}
